// Preference Manager: maps each accessibility profile to a concrete set of preferences.
export const defaultPreferences = {
  fontSize: "16px",
  fontFamily: "inherit",
  letterSpacing: "normal",
  wordSpacing: "normal",
  lineHeight: "1.5",
  backgroundColor: "#ffffff",
  textColor: "#312c51",
  buttonSize: "normal",
  focusOutline: "3px solid #4834d4",
  reducedMotion: false,
};

export const profilePreferences = {
  none: { ...defaultPreferences },

  lowVision: {
    ...defaultPreferences,
    fontSize: "20px",
    lineHeight: "1.7",
    textColor: "#000000",
    backgroundColor: "#ffffff",
    buttonSize: "large",
    focusOutline: "3px solid #000000",
  },

  dyslexia: {
    ...defaultPreferences,
    fontFamily: "'Lexend', sans-serif",
    letterSpacing: "0.5px",
    wordSpacing: "1px",
    lineHeight: "1.8",
    backgroundColor: "#fdf6ec",
    textColor: "#312c51",
  },

  colourBlind: {
    ...defaultPreferences,
    textColor: "#1a1a2e",
    backgroundColor: "#ffffff",
    focusOutline: "3px solid #312c51",
  },

  elderly: {
    ...defaultPreferences,
    fontSize: "20px",
    lineHeight: "1.7",
    buttonSize: "large",
    focusOutline: "3px solid #312c51",
    reducedMotion: true,
  },
};

export function getPreferencesForProfile(profile) {
  return profilePreferences[profile] || profilePreferences.none;
}
